    30→import org.checkerframework.checker.nullness.qual.EnsuresNonNull;
    31→import org.checkerframework.checker.nullness.qual.MonotonicNonNull;
    32→import org.mozilla.javascript.Context;
    33→import org.mozilla.javascript.ContextFactory;
    34→import org.mozilla.javascript.ScriptableObject;
    35→
    36→import javax.annotation.Nullable;
    37→import java.nio.ByteBuffer;
    38→
    39→public class JavaScriptExtractionFn implements ExtractionFn
    40→{
    41→  private static Function<Object, String> compile(String function)
    42→  {
    43→    final ContextFactory contextFactory = ContextFactory.getGlobal();
    44→    final Context context = contextFactory.enterContext();
    45→    context.setOptimizationLevel(JavaScriptConfig.DEFAULT_OPTIMIZATION_LEVEL);
    46→
    47→    final ScriptableObject scope = context.initStandardObjects();
    48→
    49→    final org.mozilla.javascript.Function fn = context.compileFunction(scope, function, "fn", 1, null);
    50→    Context.exit();
    51→
    52→
    53→    return new Function<Object, String>()
    54→    {
    55→      @Override
    56→      public String apply(Object input)
    57→      {
    58→        // ideally we need a close() function to discard the context once it is not used anymore
    59→        Context cx = Context.getCurrentContext();
    60→        if (cx == null) {
    61→          cx = contextFactory.enterContext();
    62→        }
    63→
    64→        final Object res = fn.call(cx, scope, scope, new Object[]{input});
    65→        return res != null ? Context.toString(res) : null;
    66→      }
    67→    };
    68→  }
    69→
    70→  private final String function;
    71→  private final boolean injective;
    72→  private final JavaScriptConfig config;
    73→
    74→  /**
    75→   * The field is declared volatile in order to ensure safe publication of the object
    76→   * in {@link #compile(String)} without worrying about final modifiers
    77→   * on the fields of the created object
    78→   *
    79→   * @see <a href="https://github.com/apache/druid/pull/6662#discussion_r237013157">
    80→   *     https://github.com/apache/druid/pull/6662#discussion_r237013157</a>
    81→   */
    82→  @MonotonicNonNull
    83→  private volatile Function<Object, String> fn;
    84→
    85→  @JsonCreator
    86→  public JavaScriptExtractionFn(
    87→      @JsonProperty("function") String function,
    88→      @JsonProperty("injective") boolean injective,
    89→      @JacksonInject JavaScriptConfig config
    90→  )
    91→  {
    92→    Preconditions.checkNotNull(function, "function must not be null");
    93→
    94→    this.function = function;
    95→    this.injective = injective;
    96→    this.config = config;
    97→  }
    98→
    99→  @JsonProperty
   100→  public String getFunction()
   101→  {
   102→    return function;
   103→  }
   104→
   105→  @JsonProperty
   106→  public boolean isInjective()
   107→  {
   108→    return this.injective;
   109→  }
   110→
   111→  @Override
   112→  public byte[] getCacheKey()
   113→  {
   114→    byte[] bytes = StringUtils.toUtf8(function);
   115→    return ByteBuffer.allocate(1 + bytes.length)
   116→                     .put(ExtractionCacheHelper.CACHE_TYPE_ID_JAVASCRIPT)
   117→                     .put(bytes)
   118→                     .array();
   119→  }
   120→
   121→  @Override
   122→  @Nullable
   123→  public String apply(@Nullable Object value)
   124→  {
   125→    Function<Object, String> fn = getCompiledScript();
   126→    return NullHandling.emptyToNullIfNeeded(fn.apply(value));
   127→  }
   128→
   129→  /**
   130→   * {@link #apply(Object)} can be called by multiple threads, so this function should be thread-safe to avoid extra
   131→   * script compilation.
   132→   */
   133→  @EnsuresNonNull("fn")
   134→  private Function<Object, String> getCompiledScript()
   135→  {
   136→    // JavaScript configuration should be checked when it's actually used because someone might still want Druid
   137→    // nodes to be able to deserialize JavaScript-based objects even though JavaScript is disabled.
   138→    Preconditions.checkState(config.isEnabled(), "JavaScript is disabled");
   139→
   140→    Function<Object, String> syncedFn = fn;
   141→    if (syncedFn == null) {
   142→      synchronized (config) {
   143→        syncedFn = fn;
   144→        if (syncedFn == null) {
   145→          syncedFn = compile(function);
   146→          fn = syncedFn;
   147→        }
   148→      }
   149→    }
   150→    return syncedFn;
   151→  }
   152→
   153→  @Override
   154→  @Nullable
   155→  public String apply(@Nullable String value)
   156→  {
   157→    return this.apply((Object) NullHandling.emptyToNullIfNeeded(value));
   158→  }
   159→
   160→  @Override
   161→  public String apply(long value)
   162→  {
   163→    return this.apply((Long) value);
   164→  }
   165→
   166→  @Override
   167→  public boolean preservesOrdering()
   168→  {
   169→    return false;
   170→  }
   171→
   172→  @Override
   173→  public ExtractionType getExtractionType()
   174→  {
   175→    return injective ? ExtractionType.ONE_TO_ONE : ExtractionType.MANY_TO_ONE;
   176→  }
   177→
   178→  @Override
   179→  public String toString()
   180→  {
   181→    return "JavascriptDimExtractionFn{" +
   182→           "function='" + function + '\'' +
   183→           '}';
   184→  }
   185→
   186→  @Override
   187→  public boolean equals(Object o)
   188→  {
   189→    if (this == o) {
   190→      return true;
   191→    }
   192→    if (o == null || getClass() != o.getClass()) {
   193→      return false;
   194→    }
   195→
   196→    JavaScriptExtractionFn that = (JavaScriptExtractionFn) o;
   197→
   198→    if (!function.equals(that.function)) {
   199→      return false;
   200→    }
   201→
   202→    return true;
   203→  }
   204→
   205→  @Override
   206→  public int hashCode()
   207→  {
   208→    return function.hashCode();
   209→  }
   210→}
