    45→public class JavaScriptPostAggregator implements PostAggregator
    46→{
    47→  private interface Function
    48→  {
    49→    double apply(Object[] args);
    50→  }
    51→
    52→  private static Function compile(String function)
    53→  {
    54→    final ContextFactory contextFactory = ContextFactory.getGlobal();
    55→    final Context context = contextFactory.enterContext();
    56→    context.setOptimizationLevel(JavaScriptConfig.DEFAULT_OPTIMIZATION_LEVEL);
    57→
    58→    final ScriptableObject scope = context.initStandardObjects();
    59→
    60→    final org.mozilla.javascript.Function fn = context.compileFunction(scope, function, "fn", 1, null);
    61→    Context.exit();
    62→
    63→
    64→    return new Function()
    65→    {
    66→      @Override
    67→      public double apply(Object[] args)
    68→      {
    69→        // ideally we need a close() function to discard the context once it is not used anymore
    70→        Context cx = Context.getCurrentContext();
    71→        if (cx == null) {
    72→          cx = contextFactory.enterContext();
    73→        }
    74→
    75→        return Context.toNumber(fn.call(cx, scope, scope, args));
    76→      }
    77→    };
    78→  }
    79→
    80→  private final String name;
    81→  private final List<String> fieldNames;
    82→  private final String function;
    83→  private final JavaScriptConfig config;
    84→
    85→  /**
    86→   * The field is declared volatile in order to ensure safe publication of the object
    87→   * in {@link #compile(String)} without worrying about final modifiers
    88→   * on the fields of the created object
    89→   *
    90→   * @see <a href="https://github.com/apache/druid/pull/6662#discussion_r237013157">
    91→   *     https://github.com/apache/druid/pull/6662#discussion_r237013157</a>
    92→   */
    93→  @MonotonicNonNull
    94→  private volatile Function fn;
    95→
    96→  @JsonCreator
    97→  public JavaScriptPostAggregator(
    98→      @JsonProperty("name") String name,
    99→      @JsonProperty("fieldNames") final List<String> fieldNames,
   100→      @JsonProperty("function") final String function,
   101→      @JacksonInject JavaScriptConfig config
   102→  )
   103→  {
   104→    Preconditions.checkNotNull(name, "Must have a valid, non-null post-aggregator name");
   105→    Preconditions.checkNotNull(fieldNames, "Must have a valid, non-null fieldNames");
   106→    Preconditions.checkNotNull(function, "Must have a valid, non-null function");
   107→
   108→    this.name = name;
   109→    this.fieldNames = fieldNames;
   110→    this.function = function;
   111→    this.config = config;
   112→  }
   113→
   114→  @Override
   115→  public Set<String> getDependentFields()
   116→  {
   117→    return Sets.newHashSet(fieldNames);
   118→  }
   119→
   120→  @Override
   121→  public Comparator getComparator()
   122→  {
   123→    return DoubleSumAggregator.COMPARATOR;
   124→  }
   125→
   126→  @Override
   127→  public Object compute(Map<String, Object> combinedAggregators)
   128→  {
   129→    Function fn = getCompiledScript();
   130→    final Object[] args = new Object[fieldNames.size()];
   131→    int i = 0;
   132→    for (String field : fieldNames) {
   133→      args[i++] = combinedAggregators.get(field);
   134→    }
   135→    return fn.apply(args);
   136→  }
   137→
   138→  /**
   139→   * {@link #compute} can be called by multiple threads, so this function should be thread-safe to avoid extra
   140→   * script compilation.
   141→   */
   142→  @EnsuresNonNull("fn")
   143→  private Function getCompiledScript()
   144→  {
   145→    // JavaScript configuration should be checked when it's actually used because someone might still want Druid
   146→    // nodes to be able to deserialize JavaScript-based objects even though JavaScript is disabled.
   147→    Preconditions.checkState(config.isEnabled(), "JavaScript is disabled");
   148→
   149→    Function syncedFn = fn;
   150→    if (syncedFn == null) {
   151→      synchronized (config) {
   152→        syncedFn = fn;
   153→        if (syncedFn == null) {
   154→          syncedFn = compile(function);
   155→          fn = syncedFn;
   156→        }
   157→      }
   158→    }
   159→    return syncedFn;
   160→  }
   161→
   162→  @Override
   163→  public byte[] getCacheKey()
   164→  {
   165→    return new CacheKeyBuilder(PostAggregatorIds.JAVA_SCRIPT)
   166→        .appendStrings(fieldNames)
   167→        .appendString(function)
   168→        .build();
   169→  }
